<?php session_start();if(!isset($_SESSION['user_id'])){header('Location: ../login.php');exit;}if(($_SESSION['user_role']??'')!=='admin'){http_response_code(403);exit('Admin access required.');}require_once '../includes/header.php'; ?>
<section class="admin-shell"><aside class="admin-sidebar"><div><span class="eyebrow">VS TRAVELLS</span><h2>Admin Console</h2></div><button class="side-link active" data-tab="overview">Overview</button><button class="side-link" data-tab="requests">Booking Requests</button><button class="side-link" data-tab="bookings">All Bookings</button><button class="side-link" data-tab="vehicles">Vehicles</button><button class="side-link" data-tab="customers">Customers</button><a class="side-link" href="../index.php">View customer site</a></aside><div class="admin-main"><div class="admin-top"><div><span class="eyebrow dark">ADMIN DASHBOARD</span><h1>Good day, <?php echo htmlspecialchars($_SESSION['user_name']??'Admin'); ?>.</h1></div><span class="live-dot">● System live</span></div>
<div id="adminMsg"></div><section class="admin-tab active" id="tab-overview"><div id="adminStats" class="stat-grid admin-stats"></div><div class="dashboard-grid"><div class="panel"><div class="panel-head"><h2>Pending requests</h2><button class="text-btn" onclick="showTab('requests')">Manage all</button></div><div id="overviewRequests"></div></div><div class="panel revenue-card"><span class="eyebrow">REVENUE</span><h2>Confirmed booking revenue</h2><strong id="revenueBig">₹0</strong><p>Demo revenue calculated from successfully paid and confirmed bookings.</p></div></div></section>
<section class="admin-tab" id="tab-requests"><div class="panel-head"><div><h2>Booking Requests</h2><p class="muted">Approve or reject customer requests.</p></div></div><div id="requestsList" class="request-list"></div></section>
<section class="admin-tab" id="tab-bookings"><div class="panel"><h2>All Bookings</h2><div class="table-wrap"><table class="table"><thead><tr><th>Customer</th><th>Vehicle</th><th>Dates</th><th>Total</th><th>Payment</th><th>Status</th></tr></thead><tbody id="allBookings"></tbody></table></div></div></section>
<section class="admin-tab" id="tab-vehicles"><div class="panel"><h2>Add Vehicle</h2><form id="addForm" class="form-grid"><input id="vname" placeholder="Vehicle name" required><select id="vtype"><option>Car</option><option>Bike</option></select><input type="number" min="1" id="vprice" placeholder="Price per day" required><select id="vstatus"><option>Available</option><option>Unavailable</option></select><button class="btn">Add vehicle</button></form></div><div id="adminVehicles" class="vehicle-admin-grid"></div></section>
<section class="admin-tab" id="tab-customers"><div class="panel"><h2>Customer Profiles</h2><div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Licence</th></tr></thead><tbody id="customers"></tbody></table></div></div></section></div></section>
<script>
let bookingData=[];document.querySelectorAll('.side-link[data-tab]').forEach(b=>b.onclick=()=>showTab(b.dataset.tab));function showTab(n){document.querySelectorAll('.admin-tab').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.side-link').forEach(x=>x.classList.remove('active'));document.getElementById('tab-'+n).classList.add('active');document.querySelector(`[data-tab="${n}"]`)?.classList.add('active')}
async function loadStats(){const j=await (await fetch('../api/admin/stats.php',{credentials:'include'})).json();if(!j.success)return;const s=j.data;adminStats.innerHTML=`<div class="stat"><span>Total vehicles</span><b>${s.vehicles}</b></div><div class="stat"><span>Customers</span><b>${s.customers}</b></div><div class="stat"><span>Pending requests</span><b>${s.pending}</b></div><div class="stat"><span>Confirmed</span><b>${s.confirmed}</b></div>`;revenueBig.textContent='₹'+Number(s.revenue).toLocaleString('en-IN')}
async function loadBookings(){const j=await (await fetch('../api/bookings/all.php',{credentials:'include'})).json();bookingData=j.data||[];const pending=bookingData.filter(b=>b.status==='Pending');overviewRequests.innerHTML=pending.length?pending.slice(0,4).map(reqRow).join(''):'<div class="empty-card">No pending requests.</div>';requestsList.innerHTML=pending.length?pending.map(requestCard).join(''):'<div class="empty-card">You are all caught up. No pending requests.</div>';allBookings.innerHTML=bookingData.length?bookingData.map(b=>`<tr><td><strong>${b.customerName}</strong><br><small>${b.customerEmail}</small></td><td>${b.vehicleName}</td><td>${b.startDate}<br>to ${b.endDate}</td><td>₹${Number(b.totalPrice).toLocaleString('en-IN')}</td><td>${b.paymentStatus}</td><td><span class="badge ${b.status.toLowerCase()}">${b.status}</span></td></tr>`).join(''):'<tr><td colspan="6">No bookings yet.</td></tr>'}
function reqRow(b){return `<div class="mini-request"><div><strong>${b.customerName} • ${b.vehicleName}</strong><span>${b.startDate} → ${b.endDate}</span></div><span class="badge pending">Pending</span></div>`}function requestCard(b){return `<article class="request-card"><div><span class="badge pending">Pending</span><h3>${b.vehicleName}</h3><p><strong>${b.customerName}</strong> • ${b.customerEmail}</p><p>${b.startDate} → ${b.endDate} • ${b.totalDays} days</p></div><div class="request-total"><small>Booking total</small><strong>₹${Number(b.totalPrice).toLocaleString('en-IN')}</strong><div><button class="btn" onclick="decide('${b.id}','Approved')">Approve</button><button class="btn danger" onclick="decide('${b.id}','Rejected')">Reject</button></div></div></article>`}
async function decide(id,decision){const j=await (await fetch('../api/bookings/decision.php',{method:'PUT',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify({id,decision})})).json();toast(j.message,j.success?'success':'error');loadBookings();loadStats()}
async function loadVehicles(){const j=await (await fetch('../api/vehicles/')).json();adminVehicles.innerHTML=(j.data||[]).map(v=>`<div class="admin-vehicle"><div><small>${v.type}</small><h3>${v.name}</h3><p>₹${Number(v.pricePerDay).toLocaleString('en-IN')}/day • ${v.status}</p></div><div><button class="btn secondary" onclick='editV(${JSON.stringify(v)})'>Edit</button><button class="btn danger" onclick="delV('${v.id}')">Delete</button></div></div>`).join('')}
async function send(url,method,data){return await (await fetch(url,{method,headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify(data)})).json()}addForm.onsubmit=async e=>{e.preventDefault();const j=await send('../api/vehicles/create.php','POST',{name:vname.value,type:vtype.value,pricePerDay:Number(vprice.value),status:vstatus.value});toast(j.message,j.success?'success':'error');if(j.success){addForm.reset();loadVehicles();loadStats()}};async function editV(v){const name=prompt('Vehicle name:',v.name);if(name===null)return;const type=prompt('Type:',v.type);if(type===null)return;const price=prompt('Price per day:',v.pricePerDay);if(price===null)return;const status=prompt('Status:',v.status);if(status===null)return;const j=await send('../api/vehicles/update.php','PUT',{id:v.id,name,type,pricePerDay:Number(price),status});toast(j.message,j.success?'success':'error');loadVehicles()}async function delV(id){if(!confirm('Delete this vehicle?'))return;const j=await send('../api/vehicles/delete.php','DELETE',{id});toast(j.message,j.success?'success':'error');loadVehicles();loadStats()}
async function loadCustomers(){const j=await (await fetch('../api/admin/users.php',{credentials:'include'})).json();customers.innerHTML=(j.data||[]).map(u=>`<tr><td><strong>${u.name}</strong></td><td>${u.email}</td><td>${u.phone||'—'}</td><td>${u.license||'—'}</td></tr>`).join('')||'<tr><td colspan="4">No customers.</td></tr>'}loadStats();loadBookings();loadVehicles();loadCustomers();
</script><?php require_once '../includes/footer.php'; ?>
